## Submitted testbench
```systemverilog
module tb;

  // --------------------------------------------------------------
  // Parameters and clock generation
  // --------------------------------------------------------------
  localparam int CLK_PERIOD = 10;          // 100 MHz clock
  localparam logic [15:0] PRESCALE_VAL = 16'd5;

  // --------------------------------------------------------------
  // DUT‑side signals (all declared as logic in the testbench)
  // --------------------------------------------------------------
  logic        clk = 0;
  logic        rst = 1;
  logic [15:0] prescale_val = PRESCALE_VAL;
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;
  logic        busy;
  logic        overrun_error;
  logic        frame_error;
  logic        rxd = 1'b1;   // UART receive line (idle = high)

  // --------------------------------------------------------------
  // Connect DUT ports (default DATA_WIDTH = 8)
  // --------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale_val)
  );

  // --------------------------------------------------------------
  // Drive the AXI‑Stream ready signal low at all times (back‑pressure)
  // --------------------------------------------------------------
  assign m_axis_tready = 1'b0;

  // --------------------------------------------------------------
  // Clock generation
  // --------------------------------------------------------------
  always #(CLK_PERIOD/2) clk = ~clk;

  // --------------------------------------------------------------
  // Simple wait‑for‑n‑clocks task (negative edge triggered)
  // --------------------------------------------------------------
  task automatic wait_clks (input int n);
    repeat (n) @(negedge clk);
  endtask

  // --------------------------------------------------------------
  // Frame transmitter: sends a complete UART frame on rxd
  //   data  – byte to transmit (LSB first)
  //   stop_low – 1 = force stop bit low (causes frame_error)
  // --------------------------------------------------------------
  task automatic transmit_frame (input byte unsigned data, input bit stop_low);
    int bit_clks;
    bit_clks = int'(prescale_val) * 8;

    // Start bit
    rxd = 0;
    wait_clks(bit_clks);

    // Data bits (LSB first)
    for (int i = 0; i < 8; i++) begin
      rxd = data[i];
      wait_clks(bit_clks);
    end

    // Stop bit
    if (stop_low) rxd = 0;
    else         rxd = 1;
    wait_clks(bit_clks);

    // Return to idle state
    rxd = 1;
  endtask

  // --------------------------------------------------------------
  // Main stimulus
  // --------------------------------------------------------------
  initial begin
    // -----------------------------------------------------------------
    // Reset the design
    // -----------------------------------------------------------------
    rst = 1;
    #20;
    rst = 0;
    #20;
    rst = 1;
    #20;
    rst = 0;
    #20;

    // -----------------------------------------------------------------
    // 1) Send a "bad" frame with data 0x3C and a low stop bit
    //    – this must cause frame_error while the word stays pending
    // -----------------------------------------------------------------
    transmit_frame(8'h3C, 1'b1);   // stop bit forced low → frame_error

    // Let the DUT process the frame (frame_error will be asserted for a few cycles)
    wait_clks(30);

    // -----------------------------------------------------------------
    // 2) Send a good frame with data 0xA5 and a proper stop bit
    //    – while the first word is still pending, this triggers overrun_error
    // -----------------------------------------------------------------
    transmit_frame(8'hA5, 1'b0);   // normal stop bit (high)

    // The coverage property R26 watches for:
    //   st && overrun_error && m_axis_tvalid && m_axis_tdata==8'hA5 &&
    //   $past(m_axis_tdata)==8'h3C && !$past(m_axis_tready)
    // The design will raise overrun_error a few cycles after the second
    // frame is accepted; we wait long enough for it to happen.
    wait_clks(80);

    // -----------------------------------------------------------------
    // End of simulation – the cover point has been hit
    // -----------------------------------------------------------------
    $finish;
  end

endmodule
```

